/* Bootstrap Italia / designers.italia.it derived tokens, confirmed via theme-color meta */
:root {
  --bs-primary: #0066CC;
  --bs-primary-dark: #0059B3;
  --bs-body-font: 'Titillium Web', sans-serif;
  --bs-body-color: #212529;
  --bs-body-bg: #FFFFFF;
}
body {
  font-family: var(--bs-body-font);
  color: var(--bs-body-color);
  background-color: var(--bs-body-bg);
}
.navbar { background-color: var(--bs-primary); }
.navbar a { color: #FFFFFF; font-weight: 600; }
.card-sector {
  background-color: #F8F9FA;
  border-radius: 8px;
  padding: 24px;
}
.card-sector h3 { color: var(--bs-primary); }
.badge-category {
  background-color: var(--bs-primary-dark);
  color: #FFFFFF;
  font-size: 0.75rem;
  padding: 2px 8px;
  border-radius: 4px;
}
a { color: var(--bs-primary); }
